#!/usr/bin/env python3
"""Verify this distribution; --refresh explicitly regenerates copies and metadata after edits."""
import argparse
import ast
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys

sys.dont_write_bytecode = True
ROOT = Path(__file__).resolve().parent
INDEX = 'CP_DEPLOY_V_RETRIEVAL_INDEX_v1.json'
INTEGRITY = 'DEPLOY_V_INTEGRITY_v1.json'
MANIFEST = 'DEPLOY_V_MANIFEST.json'
BASELINE = 'DEPLOY_V_BASELINE.json'
PROMPTS = ('DEPLOY_V_COPILOT_MEMORY_PROMPT.md', 'DEPLOY_V_COPILOT_MEMORY_PROMPT_URL_BOUND.md')
SOURCES = {'deployed_baseline': BASELINE, 'deployed_manifest': MANIFEST,
           'deployed_child_schema_registry': 'CP_DEPLOY_V_CHILD_SCHEMA_REGISTRY_v1.json'}
SHARED = {
    'validate_handoff.py': 'cp-0-source-readiness',
    'cp_tables.py': 'cp-0-source-readiness',
    'completeness_check.py': 'cp-0-source-readiness',
    'confidence_score.py': 'cp-0-source-readiness',
    'credit_metrics.py': 'cp-1-canonical-data-foundation',
    'covenant_headroom.py': 'cp-4-legal-covenant-interpreter',
    'recovery_waterfall.py': 'cp-3-relative-value-security-selection',
}


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()


def digest(value):
    return hashlib.sha256(value).hexdigest()


def read_json(name):
    return json.loads((ROOT / name).read_text(encoding='utf-8'))


def write_json(name, value):
    (ROOT / name).write_text(json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + '\n', encoding='utf-8')


def record(path):
    data = path.read_bytes()
    return {'bytes': len(data), 'sha256': digest(data)}


def package_files():
    paths = []
    for path in sorted(ROOT.rglob('*')):
        parts = path.relative_to(ROOT).parts
        if any(part in {'.git', '.agents', '.codex', '.DS_Store'} for part in parts):
            continue
        if path.is_symlink():
            raise ValueError(f'package contains a symlink: {path.relative_to(ROOT)}')
        if path.is_file():
            if path.suffix == '.pyc' or '__pycache__' in parts:
                raise ValueError(f'remove generated bytecode: {path.relative_to(ROOT)}')
            paths.append(path)
    return paths


def routing_index():
    index = read_json(INDEX)
    ids, slugs = set(), set()
    for row in index['skills']:
        slug = row['folder_slug']
        if not re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*', slug) or slug in slugs:
            raise ValueError(f'invalid or duplicate skill slug: {slug!r}')
        slugs.add(slug)
        if row['skill_md'] != f'skills/{slug}/SKILL.md' or not (ROOT / row['skill_md']).is_file():
            raise ValueError(f'invalid skill entry path for {slug}')
        for module_id in [row['module_id'], *row['aliases']]:
            if not re.fullmatch(r'CP-[A-Z0-9]+', module_id) or module_id in ids:
                raise ValueError(f'invalid or ambiguous command ID: {module_id!r}')
            ids.add(module_id)
        entry = (ROOT / row['skill_md']).read_text(encoding='utf-8')
        owner = re.search(r'^description: "Start-of-message trigger: Run (CP-[A-Z0-9]+) or bare \1\b', entry, re.M)
        aliases = re.findall(r'Also answers `Run (CP-[A-Z0-9]+)`\.', entry)
        if (f'\nname: {slug}\n' not in entry or not owner or owner[1] != row['module_id']
                or set(aliases) != set(row['aliases'])):
            raise ValueError(f'retrieval routing differs from SKILL.md declarations: {slug}')
    actual = {p.parent.name for p in (ROOT / 'skills').glob('*/SKILL.md')}
    if actual != slugs:
        raise ValueError('retrieval index does not match the physical skill entries')
    return index


def skill_files(index):
    files = package_files()
    slugs = {row['folder_slug'] for row in index['skills']}
    for path in files:
        if path.is_relative_to(ROOT / 'skills') and path.relative_to(ROOT / 'skills').parts[0] not in slugs:
            raise ValueError(f'unindexed skill content: {path.relative_to(ROOT)}')
    return {row['folder_slug']: {
        path.relative_to(ROOT / 'skills' / row['folder_slug']).as_posix(): record(path)
        for path in files if path.is_relative_to(ROOT / 'skills' / row['folder_slug'])
    } for row in index['skills']}


def root_file_hashes():
    return {path.relative_to(ROOT).as_posix(): record(path) for path in package_files()
            if not path.is_relative_to(ROOT / 'skills') and path != ROOT / INTEGRITY}


def build_id(index, integrity):
    return digest(canonical({'routing': {k: v for k, v in index.items() if k != 'build_id'},
                             'skills': integrity['skills'], 'source_hashes': integrity['source_hashes']}))


def routing_summary(index):
    count = sum(1 + len(row['aliases']) for row in index['skills'])
    lines = ['<!-- ROUTING_SUMMARY:BEGIN -->',
             f'Current distribution: {len(index["skills"])} physical skills and {count} command IDs, including aliases.',
             '', '| Aliases | Current owner |', '| --- | --- |']
    lines.extend(f'| {", ".join(row["aliases"])} | {row["module_id"]} |'
                 for row in index['skills'] if row['aliases'])
    return '\n'.join([*lines, '<!-- ROUTING_SUMMARY:END -->'])


def sync_copies():
    # The listed skill owns each shared source; distribution copies stay independently deployable.
    for filename, slug in SHARED.items():
        data = (ROOT / 'skills' / slug / 'scripts' / filename).read_bytes()
        for target in (ROOT / 'skills').glob(f'*/scripts/{filename}'):
            if target.read_bytes() != data:
                target.write_bytes(data)


def refresh_metadata():
    index = routing_index()
    files = skill_files(index)
    manifest, baseline, integrity = (read_json(name) for name in (MANIFEST, BASELINE, INTEGRITY))
    for document in (manifest, integrity):
        previous = {row['folder_slug']: row for row in document['skills']}
        document['skills'] = []
        for route in index['skills']:
            slug = route['folder_slug']
            current = files[slug]
            row = dict(previous.get(slug, {}), folder_slug=slug, module_id=route['module_id'], aliases=route['aliases'],
                       relative_file_hashes=current, companion_count=len(current) - 1,
                       entry_bytes=current['SKILL.md']['bytes'], entry_sha256=current['SKILL.md']['sha256'])
            document['skills'].append(row)
    manifest['physical_skill_count'] = len(files)
    manifest['physical_union'] = sorted(files)
    manifest['logical_entries'] = [dict(entry_id=mid, folder_slug=row['folder_slug'], relationship=kind)
                                   for row in index['skills'] for mid, kind in
                                   [(row['module_id'], 'physical'), *((alias, 'alias') for alias in row['aliases'])]]
    manifest['logical_skill_count'] = len(manifest['logical_entries'])
    manifest['generated_from'] = 'deployed tree via verify_package.py --refresh; upstream build system is not included'
    write_json(MANIFEST, manifest)
    baseline['packages'] = {slug: {'files': values} for slug, values in files.items()}
    baseline['baseline_digest'] = digest(canonical({k: v for k, v in baseline.items() if k != 'baseline_digest'}))
    write_json(BASELINE, baseline)
    integrity['source_hashes'] = {key: digest((ROOT / name).read_bytes()) for key, name in SOURCES.items()}
    index['build_id'] = integrity['build_id'] = build_id(index, integrity)
    write_json(INDEX, index)
    for name in PROMPTS:
        path = ROOT / name
        text = re.sub(r'(INDEX_BUILD_ID:\s*)[0-9a-f]{64}', lambda m: m[1] + index['build_id'], path.read_text())
        summary = routing_summary(index)
        if '<!-- ROUTING_SUMMARY:BEGIN -->' in text:
            text = re.sub(r'<!-- ROUTING_SUMMARY:BEGIN -->.*?<!-- ROUTING_SUMMARY:END -->',
                          lambda _: summary, text, flags=re.S)
        else:
            text = text.rstrip() + '\n\n' + summary + '\n'
        path.write_text(text, encoding='utf-8')
    integrity['root_file_hashes'] = root_file_hashes()
    write_json(INTEGRITY, integrity)


def verify_metadata():
    index = routing_index()
    files = skill_files(index)
    routes = {row['folder_slug']: row for row in index['skills']}
    manifest, baseline, integrity = (read_json(name) for name in (MANIFEST, BASELINE, INTEGRITY))
    for name, document in ((MANIFEST, manifest), (INTEGRITY, integrity)):
        if len(document['skills']) != len(files) or {r['folder_slug'] for r in document['skills']} != set(files):
            raise ValueError(f'{name}: skill inventory differs')
        for row in document['skills']:
            route = routes[row['folder_slug']]
            if row['module_id'] != route['module_id'] or set(row['aliases']) != set(route['aliases']):
                raise ValueError(f'{name}: routing differs for {row["folder_slug"]}')
            actual = files[row['folder_slug']]
            if (row['relative_file_hashes'] != actual or row['companion_count'] != len(actual) - 1
                    or row['entry_sha256'] != actual['SKILL.md']['sha256'] or row['entry_bytes'] != actual['SKILL.md']['bytes']):
                raise ValueError(f'{name}: content or size mismatch in {row["folder_slug"]}')
    logical = {(module_id, row['folder_slug'], relationship) for row in index['skills']
               for module_id, relationship in [(row['module_id'], 'physical'),
                                                *((alias, 'alias') for alias in row['aliases'])]}
    if (manifest['physical_skill_count'] != len(files) or set(manifest['physical_union']) != set(files)
            or manifest['logical_skill_count'] != len(logical) or len(manifest['logical_entries']) != len(logical)
            or {(row['entry_id'], row['folder_slug'], row['relationship']) for row in manifest['logical_entries']} != logical):
        raise ValueError('manifest command inventory or counts differ')
    if baseline['packages'] != {slug: {'files': values} for slug, values in files.items()}:
        raise ValueError('baseline file inventory differs')
    if baseline['baseline_digest'] != digest(canonical({k: v for k, v in baseline.items() if k != 'baseline_digest'})):
        raise ValueError('baseline digest differs')
    if integrity['source_hashes'] != {key: digest((ROOT / name).read_bytes()) for key, name in SOURCES.items()}:
        raise ValueError('root source hashes differ')
    if index['build_id'] != integrity['build_id'] or index['build_id'] != build_id(index, integrity):
        raise ValueError('retrieval build IDs differ')
    if integrity.get('root_file_hashes') != root_file_hashes():
        raise ValueError('root/support file inventory or hashes differ')
    for name in PROMPTS:
        text = (ROOT / name).read_text()
        ids = re.findall(r'INDEX_BUILD_ID:\s*([0-9a-f]{64})', text)
        if not ids or set(ids) != {index['build_id']} or routing_summary(index) not in text:
            raise ValueError(f'{name}: stale build ID or routing summary')
    for filename, slug in SHARED.items():
        source = (ROOT / 'skills' / slug / 'scripts' / filename).read_bytes()
        if any(path.read_bytes() != source for path in (ROOT / 'skills').glob(f'*/scripts/{filename}')):
            raise ValueError(f'shared implementation drift: {filename}')


def verify_contracts():
    """Cross-check routing and register authorities against the physical entries."""
    sys.path.insert(0, str(ROOT / 'skills/cp-os-credit-os/scripts'))
    from credit_os_v.routing import Route
    from credit_os_v.navigation import validate_catalog
    from completeness_check import load_contract
    catalog = read_json('skills/cp-os-credit-os/references/CREDIT_OS_V_MODULE_CATALOG_v2.json')
    validate_catalog(catalog)
    index = routing_index()
    routes = {row['module_id']: row for row in index['skills']}
    aliases = {alias: row['module_id'] for row in index['skills'] for alias in row['aliases']}
    if {key: value['absorbed_by'] for key, value in catalog['superseded_module_ids'].items()} != aliases:
        raise ValueError('catalog aliases differ from retrieval authority')
    for module in catalog['modules']:
        route = routes[module['module_id']]
        if module['skill_md'] != route['skill_md']:
            raise ValueError('catalog skill path differs from retrieval authority')
        text = (ROOT / route['skill_md']).read_text(encoding='utf-8')
        if '## Output profile' in text:
            ids = list(load_contract(text, module['module_id'])['registers'])
            contract = module['artifact_contract']
            if set(ids) != set(contract['required_table_ids']) or len(ids) != contract['required_table_count']:
                raise ValueError(f"register contract differs for {module['module_id']}")
    for profile_id, profile in catalog['profiles'].items():
        for selection_id, pathway in profile['pathways'].items():
            route = Route(catalog, profile_id, selection_id)
            if [n['module_id'] for n in route.nodes] != [n['module_id'] for n in pathway['nodes']]:
                raise ValueError(f'{selection_id}: packaged pathway is not dependency ordered')


def rebuild_authorities():
    """Explicit local release operation; normal verification/refresh never repins."""
    verify_contracts()
    name = 'skills/cp-os-credit-os/references/CREDIT_OS_V_AUTHORITY_BUNDLE_v2.json'
    bundle = read_json(name)
    parent = ROOT / name
    previous = bundle['authority_bundle_sha256']
    for component in bundle['components'].values():
        candidates = [ROOT / component['path'], parent.parent / Path(component['path']).name,
                      ROOT / Path(component['path']).name]
        found = next((path for path in candidates if path.is_file()), None)
        if found is None:
            if component.get('runtime_required', True):
                raise ValueError(f"cannot rebuild missing runtime authority: {component['path']}")
            continue  # Preserve unavailable upstream-only provenance pins.
        component['sha256'] = digest(found.read_bytes())
    bundle['authority_bundle_sha256'] = digest(canonical(bundle['components']))
    if bundle['authority_bundle_sha256'] != previous:
        bundle['local_rebuild'] = {'previous_authority_bundle_sha256': previous,
                                  'method': 'verify_package.py --rebuild-authorities; unavailable upstream provenance retained'}
    write_json(name, bundle)


def run_checks(integration=False):
    seen, checks = set(), 0
    for path in package_files():
        if path.suffix != '.py':
            continue
        data = path.read_bytes()
        syntax = ast.parse(data, filename=str(path))
        signature = digest(data)
        if (any(isinstance(node, ast.FunctionDef) and node.name == '_self_check' for node in syntax.body)
                and signature not in seen):
            seen.add(signature)
            subprocess.run([sys.executable, '-B', str(path), '--self-check'], cwd=ROOT, check=True)
            checks += 1
    subprocess.run([sys.executable, '-B', str(ROOT / 'skills/cp-model/scripts/validate_cp_model_inputs.py'),
                    '--self-test'], cwd=ROOT, check=True)
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE='1', DEPLOY_V_INTEGRATION='1' if integration else '0')
    subprocess.run([sys.executable, '-B', '-m', 'unittest', 'discover', '-s', 'tests', '-v'], cwd=ROOT, env=env, check=True)
    print(f'PASS: Python syntax and {checks} unique helper self-checks', flush=True)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--refresh', action='store_true', help='synchronize shared copies and regenerate metadata after intentional edits')
    parser.add_argument('--rebuild-authorities', action='store_true', help='explicitly rebuild reviewed local contract pins; requires --refresh')
    parser.add_argument('--integration', action='store_true', help='also exercise exporter dependencies and native PDF rasterization')
    args = parser.parse_args()
    try:
        if args.rebuild_authorities:
            if not args.refresh:
                raise ValueError("--rebuild-authorities requires --refresh")
            rebuild_authorities()
        verify_contracts()
        if args.refresh:
            package_files()
            sync_copies()
            run_checks(args.integration)
            refresh_metadata()
        verify_metadata()
        subprocess.run([sys.executable, '-B', str(ROOT / 'skills/cp-os-credit-os/scripts/credit_os_v_cli.py'), 'verify-authorities'], cwd=ROOT, check=True)
        if not args.refresh:
            run_checks(args.integration)
    except (OSError, ValueError, KeyError, TypeError, subprocess.CalledProcessError) as exc:
        print(f'FAIL: {exc}', file=sys.stderr)
        return 1
    print('PASS: package integrity, baseline, routing, shared copies and runtime authorities')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
